import{_ as t,o as a,c as r,a6 as o}from"./chunks/framework.CCKCzdWs.js";const u=JSON.parse('{"title":"Privacy & data flow","description":"Exactly what leaves your server and when, what never does, what Piwi does not capture, and how secrets are stored.","frontmatter":{"title":"Privacy & data flow","description":"Exactly what leaves your server and when, what never does, what Piwi does not capture, and how secrets are stored.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/privacy.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/privacy.html"}],["meta",{"property":"og:title","content":"Privacy & data flow | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Exactly what leaves your server and when, what never does, what Piwi does not capture, and how secrets are stored."}]]},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1795256374000}'),s={name:"guide/privacy.md"};function n(i,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-data-flow" tabindex="-1">Privacy &amp; data flow <a class="header-anchor" href="#privacy-data-flow" aria-label="Permalink to &quot;Privacy &amp; data flow&quot;">​</a></h1><p>Test results are revealing: they carry your source paths, error messages, screenshots of your app, network calls, and sometimes your git history. This page lists where they go.</p><p><strong>There is no telemetry</strong>, no usage analytics, no crash reporting, and no license or activation call. The server never checks for updates; the desktop app checks at startup (optional, in <strong>Settings → About</strong>) and on <strong>Check for updates</strong>, then reads the newer releases&#39; notes from GitHub, anonymously. Every outbound call the server makes is listed below; all but two are opt-in.</p><h2 id="what-leaves-your-server" tabindex="-1">What leaves your server <a class="header-anchor" href="#what-leaves-your-server" aria-label="Permalink to &quot;What leaves your server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Destination</th><th>When</th><th>Carries</th></tr></thead><tbody><tr><td>Your AI provider</td><td>Only if you configure <a href="/features/ai-diagnosis.html">AI diagnosis</a></td><td>The diagnosis context: error text, failing steps, test and related source files, console and network entries, page (ARIA/DOM) snapshots, server logs, the relevant git diff, and up to five failure screenshots by default (<code>PIWI_AI_MAX_IMAGES=0</code> sends none). <a href="/features/ai-steps.html">AI-step</a> authoring sends masked page snapshots</td></tr><tr><td>Your git host</td><td>Whenever runs report a GitHub, GitLab or Bitbucket remote (the reporter records <code>origin</code> by default)</td><td>Without a token: anonymous public-API reads of the repository&#39;s default branch and its CODEOWNERS; the desktop app reads a project&#39;s linked clone with <code>git</code> instead, and asks the host only for a commit the clone lacks. With a token: commits, diffs and files, plus the PR comments, commit statuses, heal branches and CI re-runs of the features you turn on</td></tr><tr><td>A URL you attach as a link</td><td>When someone adds a link to a run, test or cluster</td><td>A request for its title (the git host&#39;s API for an issue or PR link)</td></tr><tr><td>Your issue tracker (Jira)</td><td>Only if you <a href="/features/issue-tracking.html">connect it</a></td><td>Issue reads, and the issues and comments you file; avatars Jira names, fetched from Gravatar or Atlassian with no credentials</td></tr><tr><td>Zephyr Scale Cloud</td><td>Only if you <a href="/features/test-management.html">connect it</a></td><td>A run&#39;s results</td></tr><tr><td>Your CI server</td><td>Only if you <a href="/features/ci-rerun.html">connect one</a></td><td>The re-run or Flake Lab request</td></tr><tr><td>Your SMTP server</td><td>Only if you configure <a href="/features/notifications.html">email notifications</a></td><td>Notification and account emails</td></tr><tr><td>Slack, Teams or your webhook URLs</td><td>Only for subscriptions you create, and <a href="/features/quality-reports.html#report-schedules">report schedules</a> that name the channel</td><td>The event payload (run status, cluster, test names, file paths, short error excerpts), or the quality report</td></tr><tr><td>Your S3 endpoint</td><td>Only if you switch <a href="/operate/storage.html">storage</a> to S3</td><td>Trace files, HTML reports, attachments</td></tr><tr><td>Your PostgreSQL server</td><td>Only if you <a href="/operate/database.html#postgresql">use one</a></td><td>Everything but the files</td></tr><tr><td>Google / GitHub</td><td>Only if you enable <a href="/operate/authentication.html#oauth-google-github">OAuth sign-in</a></td><td>OAuth exchange and profile picture</td></tr><tr><td>Your OpenTelemetry collector</td><td>Only if you name one (<a href="/operate/tracing.html">tracing</a>)</td><td>A span per request and SQL statement, with its text</td></tr><tr><td>A project&#39;s OpenAPI URL</td><td>Only if a project <a href="/features/scenario-gaps.html#declared-surface">sets one</a></td><td>A request for the document</td></tr></tbody></table><p>The reporter sends your instance what its options switch on. <a href="/features/code-reach.html">Code reach</a> and <a href="/features/server-coverage.html">server coverage</a>, off by default, send repository-relative paths; line numbers and blob ids only with <code>coverage.browser</code> or <code>coverage.server</code> set to <code>&#39;functions&#39;</code> or <code>&#39;lines&#39;</code>. <code>piwi coverage upload</code> adds the commit&#39;s tracked paths. Source code and hit counts never leave.</p><p>Two rows need no setting, the anonymous git-host reads and a link&#39;s title: both fail quietly offline, so an air-gapped instance works the same.</p><p>The <strong>AI provider</strong> alone receives your source code and the full failure context, at the endpoint <em>you</em> set (a local model over Ollama or vLLM keeps it on the machine). Preview and cap that context: <a href="/features/ai-diagnosis.html#privacy">AI diagnosis → Privacy</a>.</p><h2 id="what-never-leaves-your-server" tabindex="-1">What never leaves your server <a class="header-anchor" href="#what-never-leaves-your-server" aria-label="Permalink to &quot;What never leaves your server&quot;">​</a></h2><ul><li><strong>Traces.</strong> Your instance serves the Playwright trace viewer at <code>/trace-viewer/</code>: opening a trace uploads it nowhere, unlike the hosted <code>trace.playwright.dev</code>.</li><li><strong>The API reference.</strong> Rendered in-app from your instance&#39;s OpenAPI spec, with no third-party CDN, so it works offline.</li><li><strong>Screenshots, videos, HTML reports.</strong> Stored on your disk or S3 bucket, served by your instance.</li><li><strong>HTML report execution.</strong> Reports run their scripts in a CSP sandbox with a unique opaque origin, with an in-memory Web Storage facade for Playwright&#39;s settings UI, discarded with the report; they cannot read the dashboard&#39;s cookies or local storage. Uploaded reports remain untrusted active content.</li><li><strong>Your IDE mapping.</strong> The <a href="/features/ide-integration.html">Open in editor</a> workspace root stays in your browser&#39;s local storage, never sent to the dashboard.</li></ul><h2 id="what-reaches-your-server-from-piwi-picker" tabindex="-1">What reaches your server from Piwi Picker <a class="header-anchor" href="#what-reaches-your-server-from-piwi-picker" aria-label="Permalink to &quot;What reaches your server from Piwi Picker&quot;">​</a></h2><p>The <a href="/features/extension.html">browser extension</a> works with no instance. Connecting sends the browser&#39;s and operating system&#39;s names. Connected, it reads a project&#39;s URL patterns, function catalog and locator index, and sends a URL pattern you add and a <a href="/features/bug-reports.html">bug report</a>, only on <strong>Send</strong> in its preview, which shows what goes. It carries the recorded steps with the values typed (never a password, and none with <strong>Leave out the values I typed</strong>), and whichever evidence the reporter kept ticked: screenshots of the tab, a screenshot of each step when the instance takes them, console errors and warnings, failed requests (method, path without query values, status; never a header or a body) and an outline of the page. It goes only to the connected instance, stored there like a run&#39;s evidence.</p><p><strong>Share result</strong>, after a replay of a report from the instance, sends the verdict, the site it ran on and the browser&#39;s name to that report, on <strong>Send</strong> in its preview.</p><p>Paired with the <a href="/features/extension-connection.html#pair-with-the-desktop-app">desktop app</a>, it also sends a report&#39;s title and steps, with their typed values and nothing else, to that app on this machine on <strong>Send</strong> in the <strong>Run with Playwright</strong> preview.</p><h2 id="what-piwi-deliberately-does-not-capture" tabindex="-1">What Piwi deliberately does not capture <a class="header-anchor" href="#what-piwi-deliberately-does-not-capture" aria-label="Permalink to &quot;What Piwi deliberately does not capture&quot;">​</a></h2><p>Never captured, so it cannot leak:</p><ul><li><strong>Input values in locator snapshots.</strong> The <a href="./capture-fixtures.html">capture fixtures</a> record what an element <em>is</em> (role, accessible name, test id), never what was typed into it. Traces and the failure-time ARIA snapshot keep typed values, password fields too: don&#39;t fill real secrets in tests. Error call logs never keep them, nor a request&#39;s credential headers, nor steps or an assertion&#39;s values on a password field or one whose locator names a secret (<code>Mot de passe</code>). The <strong>DOM</strong> view and AI diagnosis show them, passwords masked.</li><li><strong>Page-inventory field contents.</strong> The <a href="./reporter.html#configuration-options">page inventory</a> (<code>capturePageInventory</code>, <strong>off by default</strong>) records the names of a page&#39;s controls and links so the dashboard can tell which the suite never exercises. The name of a control that holds user input (a textbox, <code>select</code>, <code>textarea</code> or contenteditable editor) is never read from its content, so a recovery code or a draft never leaves the browser; link hrefs are stripped of their query and hash, which can carry signed tokens.</li><li><strong>Storage and cookie values.</strong> Page state records the <em>names</em> of <code>localStorage</code> /<code>sessionStorage</code> keys and their value lengths, and cookie names with their flags. Never the values. Focus, mouse and selection name elements, never values or selected text. A URL fragment&#39;s credentials are masked (<code>#access_token=[masked]</code>).</li><li><strong>Sensitive headers.</strong> <code>Authorization</code>, <code>Cookie</code> and friends are masked server-side in Piwi&#39;s trace network view, as are token-shaped strings in URLs, bodies and <a href="/reference/test-metadata.html#test-errors">test errors</a>. Piwi stores the trace file split and compressed but with its content unchanged, so the trace viewer and a downloaded trace still show them.</li><li><strong>Backend logs, in production.</strong> The <a href="./backend-logs.html">backend-log integrations</a> emit their header only in development and test environments by default.</li></ul><h2 id="secrets-at-rest" tabindex="-1">Secrets at rest <a class="header-anchor" href="#secrets-at-rest" aria-label="Permalink to &quot;Secrets at rest&quot;">​</a></h2><p>Credentials you store in the dashboard are encrypted with AES-256-GCM using <code>PIWI_SECRET_KEY</code>: AI provider keys, credentials (CI server and SCM tokens), webhook signing secrets, Slack bot tokens, the Jira and Zephyr Scale connections&#39; credentials, and a scheduled report&#39;s share-link token on its way to delivery. <strong>Set it in production.</strong> Unset, or set to the published development default, the dashboard refuses to save a credential and names the variable. Generate a key with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require(&#39;node:crypto&#39;).randomBytes(32).toString(&#39;hex&#39;))&quot;</span></span></code></pre></div><p>API keys are stored as SHA-256 hashes and shown once, at creation. A leaked database gives an attacker no usable key.</p><p>Secrets set by environment variable are never written to the database nor returned by the API: the settings UI shows them read-only, with a lock badge.</p><h2 id="the-demo" tabindex="-1">The demo <a class="header-anchor" href="#the-demo" aria-label="Permalink to &quot;The demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> has no backend: the real application runs in a service worker, against an in-browser SQLite database of fake data. Nothing you click reaches a server.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p><code>PIWI_RETENTION_DAYS</code> prunes old runs and their files nightly; <strong>Settings → Storage</strong> deletes them in bulk. Deleting a run removes its executions, traces, reports, and any evidence payloads nothing else references: <a href="/operate/storage.html#data-retention">Storage → Data retention</a>.</p><h2 id="verifying-any-of-this" tabindex="-1">Verifying any of this <a class="header-anchor" href="#verifying-any-of-this" aria-label="Permalink to &quot;Verifying any of this&quot;">​</a></h2><p>The source is public and the outbound surface small: watch the container&#39;s egress, or read <a href="https://github.com/PiwiTests/piwi/tree/main/apps/application/server/utils" target="_blank" rel="noreferrer"><code>server/utils/</code></a>: the AI provider, SCM, SMTP, notification, OAuth, Jira, Zephyr Scale, CI server, OpenTelemetry, OpenAPI, avatar and link-unfurl clients alone open a socket there; the S3 client is in <code>server/storage/</code>, PostgreSQL&#39;s in <code>server/database/</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/operate/authentication.html">Authentication</a>, <a href="/operate/api-keys.html">API keys</a> and <a href="/operate/project-access.html">Access, roles and groups</a></li><li><a href="/operate/production-checklist.html#before-you-expose-it">Production checklist</a>: hardening a public instance</li><li><a href="./comparison.html#is-my-data-safe-does-piwi-phone-home">Why Piwi?</a>: the short form</li></ul>',30)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
